(function(){
  "use strict";

  /* ============================================================
     NAVIGATION
  ============================================================ */
  const navItems = document.querySelectorAll('.nav-item');
  const pages = document.querySelectorAll('.page');
  function goTo(pageId){
    pages.forEach(p=>p.classList.toggle('active', p.id === 'page-'+pageId));
    navItems.forEach(n=>n.classList.toggle('active', n.dataset.page === pageId));
    document.getElementById('sidebar').classList.remove('open');
    window.scrollTo({top:0, behavior:'smooth'});
  }
  navItems.forEach(btn=>btn.addEventListener('click', ()=>goTo(btn.dataset.page)));
  document.querySelectorAll('[data-goto]').forEach(btn=>btn.addEventListener('click', ()=>goTo(btn.dataset.goto)));
  document.getElementById('menuToggle').addEventListener('click', ()=>document.getElementById('sidebar').classList.toggle('open'));

  /* ============================================================
     GOAL SELECTION (state)
  ============================================================ */
  const GOALS = {
    lose:    { label:'ลดน้ำหนัก',     days:'5 วัน/สัปดาห์', kcal:'ประมาณ 300 kcal', dur:'45 นาที', cat:'cardio' },
    muscle:  { label:'เพิ่มกล้ามเนื้อ', days:'4 วัน/สัปดาห์', kcal:'ประมาณ 250 kcal', dur:'40 นาที', cat:'upper' },
    fitness: { label:'เพิ่มความฟิต',   days:'6 วัน/สัปดาห์', kcal:'ประมาณ 350 kcal', dur:'50 นาที', cat:'core' },
    general: { label:'สุขภาพทั่วไป',   days:'3 วัน/สัปดาห์', kcal:'ประมาณ 200 kcal', dur:'30 นาที', cat:'stretch' }
  };
  let currentGoal = 'lose';

  document.querySelectorAll('.goal-card').forEach(card=>{
    card.addEventListener('click', ()=>{
      document.querySelectorAll('.goal-card').forEach(c=>c.classList.remove('selected'));
      card.classList.add('selected');
      currentGoal = card.dataset.goal;
      applyGoal();
      goTo('plan');
    });
  });

  function applyGoal(){
    const g = GOALS[currentGoal];
    weekPlans[1] = defaultWeekPlan(currentGoal);
    weekPlans[2] = weekPlans[1]; weekPlans[3] = weekPlans[1]; weekPlans[4] = weekPlans[1];
    document.getElementById('planGoalLabel').textContent = g.label;
    document.getElementById('planDays').textContent = g.days;
    document.getElementById('planKcal').textContent = g.kcal;
    document.getElementById('planDuration').textContent = g.dur;
    document.getElementById('settingsGoal').textContent = g.label;
    currentWeek = 1;
    document.querySelectorAll('.week-tab').forEach(t=>t.classList.toggle('active', t.dataset.week==='1'));
    buildDayList();
  }

  /* ============================================================
     HERO BACKGROUND PHOTO (upload your own, persisted per browser)
  ============================================================ */
  (function(){
    const heroBanner = document.getElementById('heroBanner');
    const heroBgBtn = document.getElementById('heroBgBtn');
    const heroImgInput = document.getElementById('heroImgInput');
    const heroBgPicker = document.getElementById('heroBgPicker');
    const heroDeco = document.getElementById('heroDeco');
    if(!heroBanner || !heroBgBtn || !heroImgInput) return;

    const THEMES = {
      ocean:  { grad:'linear-gradient(120deg,#0b1220,#16264a 60%,#1c3566)', sky0:'#3b6fed', sky1:'#f0a060', sun:'#ffd79a' },
      mint:   { grad:'linear-gradient(120deg,#0a1c16,#123a2c 60%,#1c5c43)', sky0:'#22d3a0', sky1:'#bdf5d8', sun:'#bdf5d8' },
      sunset: { grad:'linear-gradient(120deg,#241019,#3a1224 60%,#5c1c33)', sky0:'#ef5b6b', sky1:'#f0a060', sun:'#ffb199' },
      violet: { grad:'linear-gradient(120deg,#180f2b,#241a49 60%,#382a6e)', sky0:'#8b6ef2', sky1:'#f2a0e8', sun:'#d8c2ff' },
    };

    function markSelected(id){
      if(!heroBgPicker) return;
      heroBgPicker.querySelectorAll('.hero-swatch').forEach(b=>{
        b.classList.toggle('selected', b.dataset.preset === id);
      });
    }

    function applyHeroImg(dataUrl){
      if(!dataUrl) return;
      heroBanner.style.background = '';
      heroBanner.style.backgroundImage = `url("${dataUrl}")`;
      heroBanner.classList.add('has-bg');
    }

    function applyHeroTheme(id){
      const t = THEMES[id];
      if(!t) return;
      heroBanner.classList.remove('has-bg');
      heroBanner.style.backgroundImage = '';
      heroBanner.style.background = t.grad;
      if(heroDeco){
        const stops = heroDeco.querySelectorAll('#skyGrad stop');
        if(stops[0]) stops[0].setAttribute('stop-color', t.sky0);
        if(stops[1]) stops[1].setAttribute('stop-color', t.sky1);
        const sun = heroDeco.querySelector('circle');
        if(sun) sun.setAttribute('fill', t.sun);
      }
    }

    // ---- restore saved choice on load ----
    try{
      const choice = localStorage.getItem('fitplan_hero_choice');
      if(choice && THEMES[choice]){
        applyHeroTheme(choice);
        markSelected(choice);
      } else {
        const savedImg = localStorage.getItem('fitplan_hero_img');
        if(savedImg){
          applyHeroImg(savedImg);
          markSelected(choice === 'photo' ? 'photo' : 'upload');
        } else {
          const test = new Image();
          test.onload = ()=>{ applyHeroImg('images/hero-bg.jpg'); markSelected('photo'); };
          test.onerror = ()=>{ /* keep the illustrated skyline fallback */ };
          test.src = 'images/hero-bg.jpg';
        }
      }
    }catch(e){ /* ignore */ }

    heroBgBtn.addEventListener('click', ()=> heroImgInput.click());

    heroImgInput.addEventListener('change', ()=>{
      const file = heroImgInput.files && heroImgInput.files[0];
      if(!file) return;
      const reader = new FileReader();
      reader.onload = ()=>{
        applyHeroImg(reader.result);
        try{
          localStorage.setItem('fitplan_hero_img', reader.result);
          localStorage.setItem('fitplan_hero_choice', 'upload');
        }catch(e){ /* ignore, e.g. quota exceeded */ }
        markSelected('upload');
        heroImgInput.value = '';
      };
      reader.readAsDataURL(file);
    });

    if(heroBgPicker){
      heroBgPicker.addEventListener('click', (e)=>{
        const btn = e.target.closest('.hero-swatch');
        if(!btn) return;
        const preset = btn.dataset.preset;
        if(preset === 'upload'){ heroImgInput.click(); return; }
        if(preset === 'photo'){
          applyHeroImg('images/hero-bg.jpg');
          try{
            localStorage.setItem('fitplan_hero_img', 'images/hero-bg.jpg');
            localStorage.setItem('fitplan_hero_choice', 'photo');
          }catch(err){ /* ignore */ }
          markSelected('photo');
          return;
        }
        applyHeroTheme(preset);
        try{
          localStorage.removeItem('fitplan_hero_img');
          localStorage.setItem('fitplan_hero_choice', preset);
        }catch(err){ /* ignore */ }
        markSelected(preset);
      });
    }
  })();

  /* ============================================================
     TREE DATA STRUCTURE — exercise categories
     Root -> Parent (categories) -> Leaf (exercises)
  ============================================================ */
  const exerciseTree = {
    id:'root', name:'ท่าออกกำลังกายทั้งหมด', type:'root',
    children:[
      { id:'cardio', name:'คาร์ดิโอ', type:'parent', color:'#3b6fed', icon:'🏃', children:[
          { id:'ex1', name:'วิ่งบนลู่วิ่ง', type:'leaf', desc:'20-30 นาที', icon:'🏃' },
          { id:'ex2', name:'ปั่นจักรยาน', type:'leaf', desc:'25 นาที', icon:'🚴' },
          { id:'ex3', name:'กระโดดเชือก', type:'leaf', desc:'15 นาที', icon:'🤸' }
      ]},
      { id:'upper', name:'ส่วนบน', type:'parent', color:'#8b6ef2', icon:'💪', children:[
          { id:'ex4', name:'วิดพื้น', type:'leaf', desc:'3 เซต x 12 ครั้ง', icon:'💪' },
          { id:'ex5', name:'ดันบาร์เหนือศีรษะ', type:'leaf', desc:'3 เซต x 10 ครั้ง', icon:'🏋️' },
          { id:'ex6', name:'ดึงข้อ', type:'leaf', desc:'3 เซต x 8 ครั้ง', icon:'🤾' }
      ]},
      { id:'lower', name:'ส่วนล่าง', type:'parent', color:'#f0a020', icon:'🦵', children:[
          { id:'ex7', name:'สควอท', type:'leaf', desc:'3 เซต x 15 ครั้ง', icon:'🦵' },
          { id:'ex8', name:'ลันจ์', type:'leaf', desc:'3 เซต x 12 ครั้ง/ข้าง', icon:'🚶' },
          { id:'ex9', name:'ยกส้นเท้า', type:'leaf', desc:'3 เซต x 20 ครั้ง', icon:'🦶' }
      ]},
      { id:'core', name:'แกนกลาง', type:'parent', color:'#ef5b6b', icon:'🧘', children:[
          { id:'ex10', name:'แพลงก์', type:'leaf', desc:'3 เซต x 30 วินาที', icon:'🧘' },
          { id:'ex11', name:'ซิทอัพ', type:'leaf', desc:'3 เซต x 15 ครั้ง', icon:'🙆' },
          { id:'ex12', name:'บิดเอวยืน', type:'leaf', desc:'3 เซต x 20 ครั้ง', icon:'🔄' }
      ]},
      { id:'stretch', name:'ยืดเหยียด', type:'parent', color:'#22b573', icon:'🌿', children:[
          { id:'ex13', name:'ยืดหลัง', type:'leaf', desc:'2 นาที', icon:'🧎' },
          { id:'ex14', name:'ยืดขาหลัง', type:'leaf', desc:'2 นาที', icon:'🤸‍♀️' }
      ]}
    ]
  };

  /* ---- Minimal line-icon set (stroke-based, replaces emoji) ---- */
  const ICONS = {
    cardio:  '<path d="M2 13h4l2-7 3 13 2-10 2 4h7"/>',
    upper:   '<rect x="2" y="9" width="3.4" height="6" rx="1.1"/><rect x="18.6" y="9" width="3.4" height="6" rx="1.1"/><line x1="5.4" y1="12" x2="18.6" y2="12"/>',
    lower:   '<path d="M8.5 3v6l-3 5v7"/><path d="M15.5 3v6l3 5v7"/>',
    core:    '<circle cx="12" cy="12" r="7.2"/><circle cx="12" cy="12" r="2.6"/>',
    stretch: '<path d="M6.5 18C13.5 18 17 12.5 17 5c-7 0-13 3-13 11 0 .8.2 1.4.5 2z"/><path d="M6.5 18c0-3 1.8-5.6 4.3-7.4"/>',
    ex1: '<circle cx="15.5" cy="4.3" r="1.6"/><path d="M13.3 6.3l-2 3.8 3 1.8 1 5-2.3 4"/><path d="M9 13.4l3-1 3 3 3-1"/>',
    ex2: '<circle cx="6" cy="17.2" r="3"/><circle cx="18" cy="17.2" r="3"/><path d="M6 17.2l4-8.2h4l3 5.2"/><path d="M9.6 9h3.4"/><path d="M9 17.2h9"/>',
    ex3: '<circle cx="12" cy="4.2" r="1.6"/><line x1="12" y1="6.2" x2="12" y2="18"/><path d="M3 9.4c3-3 6-3 9 0s6 3 9 0"/><path d="M3 15.4c3 3 6 3 9 0s6-3 9 0"/>',
    ex4: '<circle cx="6" cy="6.8" r="1.6"/><path d="M6 8.8l3 2h9"/><path d="M9 10.8l-3 6.4"/><path d="M9 10.8l2 6.4"/><path d="M18 10.8v6.4"/>',
    ex5: '<circle cx="12" cy="4.2" r="1.6"/><path d="M6 9h12"/><path d="M8 9V7M16 9V7"/><line x1="12" y1="6.2" x2="12" y2="15"/><path d="M9 20l3-5 3 5"/>',
    ex6: '<line x1="4" y1="5" x2="20" y2="5"/><circle cx="12" cy="9.2" r="1.6"/><path d="M9 6.4l3 2.8 3-2.8"/><line x1="12" y1="11.2" x2="12" y2="17"/><path d="M9 20l3-3 3 3"/>',
    ex7: '<circle cx="12" cy="4.2" r="1.6"/><path d="M8 8.2h8"/><line x1="12" y1="6.2" x2="12" y2="11"/><path d="M8 20v-4l4-3 4 3v4"/>',
    ex8: '<circle cx="9.5" cy="4.2" r="1.6"/><line x1="9.5" y1="6.2" x2="9.5" y2="11"/><path d="M6 20l3.5-9"/><path d="M13.5 20v-6l-3-3"/>',
    ex9: '<path d="M9 3v9.5A3.3 3.3 0 0 0 12.3 15.8h1.4A3.3 3.3 0 0 1 17 19.1V21H10a4 4 0 0 1-4-4V6a3 3 0 0 1 3-3z"/>',
    ex10:'<circle cx="5" cy="8.6" r="1.6"/><path d="M5 10.6l4 1h11"/><path d="M9 11.6l-3 7.8"/><line x1="20" y1="11.6" x2="20" y2="19.4"/>',
    ex11:'<circle cx="6.3" cy="15" r="1.6"/><path d="M6.3 16.6l4-2.6 5.7 2.6"/><line x1="10.3" y1="14" x2="10.3" y2="7.6"/><path d="M16 20l4-3.4"/>',
    ex12:'<circle cx="12" cy="4.2" r="1.6"/><line x1="12" y1="6.2" x2="12" y2="14"/><path d="M6.5 9.2c2 1.8 3.7 1.8 5.5 1.8s3.5 0 5.5-1.8"/><path d="M9 20l3-6 3 6"/>',
    ex13:'<circle cx="12" cy="4.2" r="1.6"/><line x1="12" y1="6.2" x2="12" y2="11"/><path d="M8 20c1-4.4 2-6.4 4-9.4 2 3 3 5 4 9.4"/>',
    ex14:'<circle cx="7" cy="5.2" r="1.6"/><path d="M7 7.2v6l4 2"/><path d="M11 15.2l6-2"/><path d="M7 13.2l-2 6.8"/><path d="M11 15.2l1 4.8"/>'
  };
  function iconSvg(key, size){
    size = size || 20;
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${ICONS[key]||''}</svg>`;
  }
  const CAMERA_ICON = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h3.2l1.8-2h6l1.8 2H20v11H4z"/><circle cx="12" cy="13.2" r="3.1"/></svg>';
  const ZOOM_ICON = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="10.5" cy="10.5" r="6.5"/><line x1="15.3" y1="15.3" x2="20" y2="20"/><line x1="10.5" y1="7.7" x2="10.5" y2="13.3"/><line x1="7.7" y1="10.5" x2="13.3" y2="10.5"/></svg>';
  const CLOCK_ICON = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>';

  /* ---- per-exercise custom images (uploaded by the user for this session) ---- */
  let exImages = {};
  try{
    const saved = localStorage.getItem('fitplan_ex_images');
    if(saved) exImages = JSON.parse(saved);
  }catch(e){ exImages = {}; }
  function saveExImages(){
    try{ localStorage.setItem('fitplan_ex_images', JSON.stringify(exImages)); }catch(e){ /* ignore */ }
  }

  function getLeaves(node){
    if(node.type === 'leaf') return [node];
    return (node.children||[]).flatMap(getLeaves);
  }
  const ALL_EXERCISES = getLeaves(exerciseTree).map(ex=>{
    const parent = exerciseTree.children.find(c=>c.children.includes(ex));
    return Object.assign({}, ex, {catId:parent.id, catName:parent.name, catColor:parent.color});
  });

  /* ---- render category chips (built from Tree's Parent level) ---- */
  const catRow = document.getElementById('catRow');
  let activeCat = 'all';
  function buildCatRow(){
    catRow.innerHTML = '';
    const allChip = document.createElement('button');
    allChip.className = 'cat-chip active';
    allChip.innerHTML = iconSvg('core',13.5)+'<span>ทั้งหมด</span>';
    allChip.addEventListener('click', ()=>{ activeCat='all'; setActiveChip(allChip); renderExercises(); });
    catRow.appendChild(allChip);
    exerciseTree.children.forEach(cat=>{
      const chip = document.createElement('button');
      chip.className = 'cat-chip';
      chip.innerHTML = iconSvg(cat.id,13.5)+'<span>'+cat.name+'</span>';
      chip.addEventListener('click', ()=>{ activeCat=cat.id; setActiveChip(chip); renderExercises(); });
      catRow.appendChild(chip);
    });
  }
  function setActiveChip(el){
    catRow.querySelectorAll('.cat-chip').forEach(c=>c.classList.remove('active'));
    el.classList.add('active');
  }

  /* ---- render exercise grid (filtered via Tree leaves + search) ---- */
  const exGrid = document.getElementById('exGrid');
  const exSearch = document.getElementById('exSearch');
  /* built-in photos matching each exercise pose, keyed by exercise id (works even without the images/ folder) */
  /* built-in photos matching each exercise pose (base64), keyed by exercise id.
     these work everywhere (no images/ folder needed) and are overridden by
     a user's own upload, or by a matching file in images/<id>.jpg if present. */
  const DEFAULT_EX_IMAGES = {
    ex1: 'data:image/jpeg;base64,',
    ex2: 'data:image/jpeg;base64,',
    ex3: 'data:image/jpeg;base64,',
    ex4: 'data:image/jpeg;base64,',
    ex5: 'data:image/jpeg;base64,',
    ex6: 'data:image/jpeg;base64,',
    ex7: 'data:image/jpeg;base64,',
    ex8: 'data:image/jpeg;base64,',
    ex9: 'data:image/jpeg;base64,',
    ex10: 'data:image/jpeg;base64,',
    ex11: 'data:image/jpeg;base64,',
    ex12: 'data:image/jpeg;base64,',
    ex13: 'data:image/jpeg;base64,',
    ex14: 'data:image/jpeg;base64,'
  };
  function renderExercises(){
    const term = exSearch.value.trim().toLowerCase();
    const list = ALL_EXERCISES.filter(ex=>{
      const catOk = activeCat==='all' || ex.catId===activeCat;
      const searchOk = !term || ex.name.toLowerCase().includes(term);
      return catOk && searchOk;
    });
    exGrid.innerHTML = list.map(ex=>{
      const customImg = exImages[ex.id];
      const src = customImg || DEFAULT_EX_IMAGES[ex.id] || `images/${ex.id}.jpg`;
      const thumbInner = `
        <img class="ex-thumb-img" src="${src}" alt="${ex.name}" onerror="window.__exImgError&&window.__exImgError(this)">
        <button class="thumb-upload" type="button" data-id="${ex.id}" title="เปลี่ยนรูปภาพ">${CAMERA_ICON}</button>
        <button class="thumb-empty" type="button" data-id="${ex.id}" title="เพิ่มรูปภาพ" style="display:none;">
          <span class="thumb-empty-icon" style="color:${ex.catColor};">${iconSvg(ex.id,24)}</span>
          <span class="thumb-empty-label">เพิ่มรูปภาพ</span>
        </button>`;
      return `
      <div class="ex-card">
        <div class="ex-thumb" data-id="${ex.id}" data-name="${ex.name}" data-desc="${ex.desc}" style="background:linear-gradient(160deg, ${ex.catColor}26, ${ex.catColor}0d);">
          ${thumbInner}
          <span class="play">${ZOOM_ICON}</span>
        </div>
        <div class="ex-body">
          <div class="name">${ex.name}</div>
          <span class="tag" style="background:${hexToSoft(ex.catColor)}; color:${ex.catColor};">${ex.catName}</span>
          <div class="meta">${CLOCK_ICON}<span>${ex.desc}</span></div>
        </div>
      </div>`;
    }).join('') || '<div style="grid-column:1/-1; color:var(--ink-soft); font-size:13px; padding:20px 0;">ไม่พบท่าออกกำลังกายที่ค้นหา</div>';
    exGrid.querySelectorAll('.ex-thumb').forEach(thumb=>{
      thumb.addEventListener('click', (e)=>{
        if(e.target.closest('.thumb-upload, .thumb-empty')) return;
        const img = thumb.querySelector('.ex-thumb-img');
        if(!img || img.style.display === 'none') return;
        openImgLightbox(img.src, thumb.dataset.name, thumb.dataset.desc);
      });
    });
  }
  const imgModalBg = document.getElementById('imgModalBg');
  const imgModalBox = document.getElementById('imgModalBox');
  function openImgLightbox(src, name, desc){
    imgModalBox.innerHTML = `
      <img class="img-modal-photo" src="${src}" alt="${name}">
      <div class="img-modal-body">
        <h3>${name}</h3>
        <p>${desc}</p>
      </div>
      <button class="modal-close" id="imgModalClose">ปิด</button>
    `;
    document.getElementById('imgModalClose').addEventListener('click', ()=>imgModalBg.classList.remove('show'));
    imgModalBg.classList.add('show');
  }
  imgModalBg.addEventListener('click', (e)=>{ if(e.target===imgModalBg) imgModalBg.classList.remove('show'); });
  /* if a card's image (custom upload or images/<id>.jpg) fails to load, fall back to the icon CTA */
  window.__exImgError = function(imgEl){
    imgEl.style.display = 'none';
    const wrap = imgEl.parentElement;
    const camBtn = wrap.querySelector('.thumb-upload');
    const emptyBtn = wrap.querySelector('.thumb-empty');
    if(camBtn) camBtn.style.display = 'none';
    if(emptyBtn) emptyBtn.style.display = 'flex';
  };
  function hexToSoft(hex){
    const map = {'#3b6fed':'#e8effe','#8b6ef2':'#efeafd','#f0a020':'#fdf1de','#ef5b6b':'#fdeaec','#22b573':'#e4f8ee'};
    return map[hex] || '#eef1f7';
  }
  exSearch.addEventListener('input', renderExercises);
  buildCatRow();
  renderExercises();

  /* ---- image upload: click the empty-state button, or the small camera badge once an image is set ---- */
  let pendingUploadId = null;
  const exImgInput = document.getElementById('exImgInput');
  exGrid.addEventListener('click', (e)=>{
    const btn = e.target.closest('.thumb-upload, .thumb-empty');
    if(!btn) return;
    pendingUploadId = btn.dataset.id;
    exImgInput.click();
  });
  exImgInput.addEventListener('change', ()=>{
    const file = exImgInput.files && exImgInput.files[0];
    if(!file || !pendingUploadId) return;
    const reader = new FileReader();
    reader.onload = ()=>{
      exImages[pendingUploadId] = reader.result;
      saveExImages();
      renderExercises();
      exImgInput.value = '';
    };
    reader.readAsDataURL(file);
  });

  /* ============================================================
     TREE RENDER (SVG) — Root / Parent / Leaf, DFS layout
  ============================================================ */
  function renderTreeSvg(){
    const svg = document.getElementById('treeSvg');
    const W=760, H=360;
    const rootPos = {x:60, y:180};
    const catCount = exerciseTree.children.length;
    const catGapY = H/(catCount);
    let html = '';
    const lines = [];
    const nodes = [];

    nodes.push({x:rootPos.x, y:rootPos.y, r:22, fill:'#0b1220', label:'ทั้งหมด', textColor:'#fff', fs:11});

    exerciseTree.children.forEach((cat, ci)=>{
      const cx = 300, cy = catGapY*ci + catGapY/2;
      lines.push([rootPos.x, rootPos.y, cx, cy, '#c7cede']);
      nodes.push({x:cx, y:cy, r:19, fill:cat.color, label:cat.icon, textColor:'#fff', fs:13});

      const leafCount = cat.children.length;
      const leafGap = catGapY/(leafCount+0.3);
      cat.children.forEach((leaf, li)=>{
        const lx = 560, ly = (catGapY*ci) + leafGap*(li+0.75);
        lines.push([cx, cy, lx, ly, '#dfe3ee']);
        nodes.push({x:lx, y:ly, r:5.5, fill:'#22b573', label:'', textColor:'', fs:0, isLeaf:true, name:leaf.name});
      });
    });

    lines.forEach(l=>{
      html += `<line x1="${l[0]}" y1="${l[1]}" x2="${l[2]}" y2="${l[3]}" stroke="${l[4]}" stroke-width="1.6"/>`;
    });
    nodes.forEach(n=>{
      html += `<circle cx="${n.x}" cy="${n.y}" r="${n.r}" fill="${n.fill}"/>`;
      if(n.label) html += `<text x="${n.x}" y="${n.y+4}" text-anchor="middle" font-size="${n.fs}" fill="${n.textColor}">${n.label}</text>`;
      if(n.isLeaf) html += `<text x="${n.x+9}" y="${n.y+3.5}" font-size="9.6" fill="#5b6478">${n.name}</text>`;
    });
    html += `<text x="${rootPos.x}" y="${rootPos.y+38}" text-anchor="middle" font-size="9.5" fill="#5b6478">Root</text>`;
    html += `<text x="300" y="${catGapY*0.5-30}" text-anchor="middle" font-size="9.5" fill="#5b6478">Parent</text>`;
    html += `<text x="560" y="14" text-anchor="middle" font-size="9.5" fill="#5b6478">Leaf</text>`;
    svg.innerHTML = html;
  }
  renderTreeSvg();

  /* ============================================================
     GRAPH DATA STRUCTURE — weighted adjacency list (circuit stations)
  ============================================================ */
  const stationMeta = {
    A:{name:'อุ่นเครื่อง', x:70,  y:70},
    B:{name:'วิ่งเบาๆ',    x:230, y:40},
    C:{name:'สควอท',      x:380, y:90},
    D:{name:'วิดพื้น',     x:230, y:180},
    E:{name:'แพลงก์',      x:380, y:230},
    F:{name:'ยืดเหยียด',   x:150, y:290},
    G:{name:'คูลดาวน์',    x:330, y:320}
  };
  const edgeList = [
    ['A','B',20], ['B','C',15], ['B','D',25], ['C','D',10],
    ['C','E',20], ['D','E',15], ['D','F',30], ['E','F',20],
    ['E','G',25], ['F','G',15]
  ];
  const graph = {};
  Object.keys(stationMeta).forEach(k=>graph[k]=[]);
  edgeList.forEach(([a,b,w])=>{
    graph[a].push({to:b, w}); graph[b].push({to:a, w});
  });

  /* ---- BFS: fewest-stations path ---- */
  function bfsPath(start, end){
    const queue = [[start]];
    const seen = new Set([start]);
    while(queue.length){
      const path = queue.shift();
      const node = path[path.length-1];
      if(node === end) return path;
      for(const e of graph[node]){
        if(!seen.has(e.to)){ seen.add(e.to); queue.push(path.concat(e.to)); }
      }
    }
    return null;
  }

  /* ---- DFS: traversal visiting every reachable station ---- */
  function dfsTraversal(start){
    const visited = new Set();
    const order = [];
    (function walk(node){
      visited.add(node);
      order.push(node);
      for(const e of graph[node]){
        if(!visited.has(e.to)) walk(e.to);
      }
    })(start);
    return order;
  }

  /* ---- Dijkstra: minimum total-weight path ---- */
  function dijkstra(start, end){
    const dist = {}, prev = {}, visited = new Set();
    Object.keys(stationMeta).forEach(k=>dist[k]=Infinity);
    dist[start]=0;
    while(visited.size < Object.keys(stationMeta).length){
      let u=null, best=Infinity;
      for(const k in dist){ if(!visited.has(k) && dist[k]<best){ best=dist[k]; u=k; } }
      if(u===null) break;
      visited.add(u);
      for(const e of graph[u]){
        const nd = dist[u]+e.w;
        if(nd < dist[e.to]){ dist[e.to]=nd; prev[e.to]=u; }
      }
    }
    if(dist[end]===Infinity) return null;
    const path=[end];
    let cur=end;
    while(prev[cur]){ cur=prev[cur]; path.unshift(cur); }
    return {path, total:dist[end]};
  }

  /* ---- render graph SVG (base + optional highlighted path) ---- */
  function renderGraphSvg(highlightPath){
    const svg = document.getElementById('graphSvg');
    let html = '';
    const hp = highlightPath || [];
    const hpEdges = new Set();
    for(let i=0;i<hp.length-1;i++){ hpEdges.add(hp[i]+'-'+hp[i+1]); hpEdges.add(hp[i+1]+'-'+hp[i]); }

    edgeList.forEach(([a,b,w])=>{
      const pa=stationMeta[a], pb=stationMeta[b];
      const on = hpEdges.has(a+'-'+b);
      html += `<line x1="${pa.x}" y1="${pa.y}" x2="${pb.x}" y2="${pb.y}" stroke="${on?'#ef5b6b':'#c7cede'}" stroke-width="${on?3.4:1.8}"/>`;
      const mx=(pa.x+pb.x)/2, my=(pa.y+pb.y)/2;
      html += `<rect x="${mx-11}" y="${my-8}" width="22" height="14" rx="4" fill="${on?'#fdeaec':'#fff'}"/>`;
      html += `<text x="${mx}" y="${my+3}" text-anchor="middle" font-size="9" fill="${on?'#ef5b6b':'#8b95ad'}">${w}</text>`;
    });
    Object.entries(stationMeta).forEach(([id,p])=>{
      const on = hp.includes(id);
      html += `<circle cx="${p.x}" cy="${p.y}" r="18" fill="${on?'#ef5b6b':'#3b6fed'}"/>`;
      html += `<text x="${p.x}" y="${p.y+4}" text-anchor="middle" font-size="12" font-weight="700" fill="#fff">${id}</text>`;
      html += `<text x="${p.x}" y="${p.y+32}" text-anchor="middle" font-size="9.5" fill="#5b6478">${p.name}</text>`;
    });
    svg.innerHTML = html;
  }
  renderGraphSvg();

  const gStart = document.getElementById('gStart');
  const gEnd = document.getElementById('gEnd');
  Object.entries(stationMeta).forEach(([id,p])=>{
    gStart.innerHTML += `<option value="${id}">${id} — ${p.name}</option>`;
    gEnd.innerHTML += `<option value="${id}">${id} — ${p.name}</option>`;
  });
  gStart.value='A'; gEnd.value='G';

  const pathResult = document.getElementById('pathResult');
  function showResult(text, path){
    pathResult.classList.add('show');
    pathResult.innerHTML = text;
    renderGraphSvg(path);
  }
  document.getElementById('btnBfs').addEventListener('click', ()=>{
    const p = bfsPath(gStart.value, gEnd.value);
    if(!p) return showResult('ไม่พบเส้นทาง');
    showResult(`<b>BFS</b> เส้นทางน้อยสถานีสุด: ${p.join(' → ')} &nbsp;(${p.length-1} ช่วงการเดิน)`, p);
  });
  document.getElementById('btnDij').addEventListener('click', ()=>{
    const r = dijkstra(gStart.value, gEnd.value);
    if(!r) return showResult('ไม่พบเส้นทาง');
    showResult(`<b>Weighted (Dijkstra)</b> เส้นทางเร็วสุด: ${r.path.join(' → ')} &nbsp;(รวม ${r.total} วินาที)`, r.path);
  });
  document.getElementById('btnDfs').addEventListener('click', ()=>{
    const order = dfsTraversal(gStart.value);
    showResult(`<b>DFS</b> วงจรครบทุกสถานีจาก ${gStart.value}: ${order.join(' → ')}`, order);
  });

  /* ============================================================
     PLAN PAGE — day list (weekly schedule)
  ============================================================ */
  /* ---- default per-goal weekly template (used unless a custom/beginner plan is generated) ---- */
  const DEFAULT_PLANS = {
    lose:[
      {day:'วันที่ 1', catId:'cardio', title:'คาร์ดิโอ + ส่วนล่าง', sub:'45 นาที | เผาผลาญเข้มข้น', tagColor:'#3b6fed'},
      {day:'วันที่ 2', catId:'upper', title:'คาร์ดิโอ + ส่วนบน', sub:'45 นาที | เสริมสร้างกล้ามเนื้อ', tagColor:'#8b6ef2'},
      {day:'วันที่ 3', catId:'stretch', title:'พัก / ยืดคลายกล้ามเนื้อ', sub:'– | ฟื้นฟูร่างกาย', tagColor:'#22b573'},
      {day:'วันที่ 4', catId:'cardio', title:'คาร์ดิโอ + ทั้งตัว', sub:'45 นาที | แผนสลับเบิร์น', tagColor:'#f0a020'},
      {day:'วันที่ 5', catId:'core', title:'แกนกลาง + แขนกลาง', sub:'45 นาที | สร้างความแข็งแรง', tagColor:'#ef5b6b'}
    ]
  };
  function defaultWeekPlan(goalId){
    if(DEFAULT_PLANS[goalId]) return DEFAULT_PLANS[goalId];
    // build a simple plan cycling through categories starting from the goal's primary category
    const g = GOALS[goalId];
    const startIdx = exerciseTree.children.findIndex(c=>c.id===g.cat);
    const dayCount = parseInt(g.days,10) || 3;
    const palette = ['#3b6fed','#8b6ef2','#22b573','#f0a020','#ef5b6b'];
    const plan = [];
    for(let i=0;i<dayCount;i++){
      const cat = exerciseTree.children[(startIdx+i) % exerciseTree.children.length];
      plan.push({ day:'วันที่ '+(i+1), catId:cat.id, title:cat.name, sub:g.dur+' | แผนสำหรับ'+g.label, tagColor:palette[i%palette.length] });
    }
    return plan;
  }
  const weekPlans = { 1:defaultWeekPlan('lose') };
  weekPlans[2]=weekPlans[1]; weekPlans[3]=weekPlans[1]; weekPlans[4]=weekPlans[1];

  const dayList = document.getElementById('dayList');
  let currentWeek = 1;
  function buildDayList(){
    const plan = weekPlans[currentWeek];
    dayList.innerHTML = plan.map((d,i)=>{
      const cat = exerciseTree.children.find(c=>c.id===d.catId);
      const exercises = cat ? cat.children.slice(0,3) : [];
      return `
      <div class="day-row">
        <div class="day-row-head" data-idx="${i}">
          <div class="day-badge" style="background:${hexToSoft(d.tagColor)}; color:${d.tagColor};">${cat?cat.icon:'🧘'}</div>
          <div class="info">
            <div class="d-title">${d.day}</div>
            <div class="d-sub">${d.title} · ${d.sub}</div>
          </div>
          <span class="day-tag" style="background:${hexToSoft(d.tagColor)}; color:${d.tagColor};">ดูรายละเอียด</span>
          <svg class="chev" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 6 15 12 9 18"/></svg>
        </div>
        <div class="day-detail">
          ${exercises.map(ex=>`<div class="ex-mini">${ex.icon} <b>${ex.name}</b> — ${ex.desc}</div>`).join('') || '<div class="ex-mini">ท่ายืดผ่อนคลายอิสระ</div>'}
        </div>
      </div>`;
    }).join('');

    dayList.querySelectorAll('.day-row-head').forEach(head=>{
      head.addEventListener('click', ()=>{
        const detail = head.nextElementSibling;
        const chev = head.querySelector('.chev');
        detail.classList.toggle('open');
        chev.classList.toggle('open');
      });
    });
  }
  document.querySelectorAll('.week-tab').forEach(tab=>{
    tab.addEventListener('click', ()=>{
      document.querySelectorAll('.week-tab').forEach(t=>t.classList.remove('active'));
      tab.classList.add('active');
      currentWeek = Number(tab.dataset.week);
      buildDayList();
    });
  });
  applyGoal();

  /* ============================================================
     STATS PAGE — simple SVG charts
  ============================================================ */
  function lineChart(svgId, values, labels, color){
    const svg = document.getElementById(svgId);
    const W=400,H=190, padL=34, padR=14, padT=18, padB=26;
    const min=Math.min(...values), max=Math.max(...values);
    const span = (max-min)||1;
    const stepX = (W-padL-padR)/(values.length-1);
    const pts = values.map((v,i)=>{
      const x = padL + stepX*i;
      const y = padT + (H-padT-padB) * (1 - (v-min)/span);
      return [x,y];
    });
    let html = '';
    for(let g=0; g<=3; g++){
      const y = padT + (H-padT-padB)*g/3;
      html += `<line x1="${padL}" y1="${y}" x2="${W-padR}" y2="${y}" stroke="#e6e9f0" stroke-width="1"/>`;
    }
    html += `<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>`;
    pts.forEach((p,i)=>{
      html += `<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="${color}"/>`;
      html += `<text x="${p[0]}" y="${H-8}" text-anchor="middle" font-size="9.5" fill="#8b95ad">${labels[i]}</text>`;
    });
    html += `<rect x="${pts[pts.length-1][0]-22}" y="${pts[pts.length-1][1]-24}" width="46" height="17" rx="8" fill="${color}"/>`;
    html += `<text x="${pts[pts.length-1][0]}" y="${pts[pts.length-1][1]-11.5}" text-anchor="middle" font-size="9.5" fill="#fff">${values[values.length-1]}</text>`;
    svg.innerHTML = html;
  }
  function barChart(svgId, values, labels, color){
    const svg = document.getElementById(svgId);
    const W=400,H=190, padL=10, padR=10, padT=26, padB=26;
    const max = Math.max(...values)*1.15;
    const bw = (W-padL-padR)/values.length*0.5;
    const gap = (W-padL-padR)/values.length;
    let html='';
    values.forEach((v,i)=>{
      const bh = (H-padT-padB)*(v/max);
      const x = padL + gap*i + (gap-bw)/2;
      const y = H-padB-bh;
      html += `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="6" fill="${color}" opacity="${1 - i*0.12}"/>`;
      html += `<text x="${x+bw/2}" y="${y-7}" text-anchor="middle" font-size="10.5" font-weight="700" fill="#0f172a">${v}%</text>`;
      html += `<text x="${x+bw/2}" y="${H-9}" text-anchor="middle" font-size="9.5" fill="#8b95ad">${labels[i]}</text>`;
    });
    svg.innerHTML = html;
  }
  lineChart('weightChart', [70,68,65,62.5], ['สัปดาห์ 1','สัปดาห์ 2','สัปดาห์ 3','สัปดาห์ 4'], '#3b6fed');
  barChart('fatChart', [28,25,22,20], ['สัปดาห์ 1','สัปดาห์ 2','สัปดาห์ 3','สัปดาห์ 4'], '#8b6ef2');

  /* ============================================================
     QUIZ MODAL
  ============================================================ */
  const modalBg = document.getElementById('modalBg');
  const modalBox = document.getElementById('modalBox');
  const quizSteps = [
    { q:'เป้าหมายหลักของคุณตอนนี้คืออะไร?', opts:[
        {t:'อยากลดไขมันส่วนเกิน', goal:'lose'},
        {t:'อยากมีกล้ามเนื้อชัดขึ้น', goal:'muscle'},
        {t:'อยากวิ่ง/ออกกำลังได้นานขึ้น', goal:'fitness'},
        {t:'แค่อยากขยับร่างกายให้แข็งแรง', goal:'general'}
    ]}
  ];
  document.getElementById('openQuiz').addEventListener('click', ()=>{
    renderQuiz(0);
    modalBg.classList.add('show');
  });
  function renderQuiz(stepIdx){
    const step = quizSteps[stepIdx];
    modalBox.innerHTML = `<h3>${step.q}</h3>` +
      step.opts.map(o=>`<button class="q-opt" data-goal="${o.goal}">${o.t}</button>`).join('') +
      `<button class="modal-close" id="closeQuiz">ปิด</button>`;
    modalBox.querySelectorAll('.q-opt').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        currentGoal = btn.dataset.goal;
        document.querySelectorAll('.goal-card').forEach(c=>c.classList.toggle('selected', c.dataset.goal===currentGoal));
        applyGoal();
        modalBg.classList.remove('show');
        goTo('plan');
      });
    });
    document.getElementById('closeQuiz').addEventListener('click', ()=>modalBg.classList.remove('show'));
  }
  modalBg.addEventListener('click', (e)=>{ if(e.target===modalBg) modalBg.classList.remove('show'); });

  /* ============================================================
     BEGINNER RECOMMENDED COURSE (home page)
  ============================================================ */
  function applyBeginnerPlan(){
    const cats = ['stretch','cardio','core'];
    const palette = ['#22b573','#3b6fed','#ef5b6b'];
    const plan = cats.map((catId,i)=>{
      const cat = exerciseTree.children.find(c=>c.id===catId);
      return { day:'วันที่ '+(i+1), catId:catId, title:cat.name+' (เบาๆ)', sub:'25 นาที | เหมาะสำหรับมือใหม่', tagColor:palette[i] };
    });
    weekPlans[1]=plan; weekPlans[2]=plan; weekPlans[3]=plan; weekPlans[4]=plan;
    document.getElementById('planGoalLabel').textContent = 'คอร์สสำหรับมือใหม่';
    document.getElementById('planDays').textContent = '3 วัน/สัปดาห์';
    document.getElementById('planKcal').textContent = 'ประมาณ 180 kcal';
    document.getElementById('planDuration').textContent = '25 นาที';
    document.getElementById('settingsGoal').textContent = 'คอร์สสำหรับมือใหม่';
    document.querySelectorAll('.goal-card').forEach(c=>c.classList.remove('selected'));
    currentWeek = 1;
    document.querySelectorAll('.week-tab').forEach(t=>t.classList.toggle('active', t.dataset.week==='1'));
    buildDayList();
    goTo('plan');
  }
  const startBeginnerBtn = document.getElementById('startBeginner');
  if(startBeginnerBtn) startBeginnerBtn.addEventListener('click', applyBeginnerPlan);

  /* ============================================================
     BUILD-YOUR-OWN-PLAN MODAL
  ============================================================ */
  const builderModalBg = document.getElementById('builderModalBg');
  const builderModalBox = document.getElementById('builderModalBox');
  let builderState = { days:3, duration:30, cats:['cardio','core'] };

  function renderBuilder(){
    const catsHtml = exerciseTree.children.map(cat=>{
      const active = builderState.cats.includes(cat.id) ? 'active' : '';
      return `<button type="button" class="cat-chip builder-chip ${active}" data-cat="${cat.id}">${iconSvg(cat.id,13.5)}<span>${cat.name}</span></button>`;
    }).join('');
    const daysHtml = [2,3,4,5,6].map(n=>`<button type="button" class="chip-opt ${builderState.days===n?'active':''}" data-days="${n}">${n} วัน</button>`).join('');
    const durHtml = [20,30,45,60].map(n=>`<button type="button" class="chip-opt ${builderState.duration===n?'active':''}" data-dur="${n}">${n} นาที</button>`).join('');
    builderModalBox.innerHTML = `
      <h3>สร้างแผนออกกำลังกายของคุณเอง</h3>
      <div class="builder-group">
        <div class="builder-label">จำนวนวันต่อสัปดาห์</div>
        <div class="chip-row">${daysHtml}</div>
      </div>
      <div class="builder-group">
        <div class="builder-label">ระยะเวลาต่อวัน</div>
        <div class="chip-row">${durHtml}</div>
      </div>
      <div class="builder-group">
        <div class="builder-label">หมวดที่อยากเน้น (เลือกได้หลายหมวด)</div>
        <div class="chip-row">${catsHtml}</div>
      </div>
      <button class="btn" id="genPlanBtn" style="width:100%; justify-content:center; margin-top:4px;">สร้างแผนของฉัน</button>
      <button class="modal-close" id="builderClose">ปิด</button>
    `;
    builderModalBox.querySelectorAll('[data-days]').forEach(b=>b.addEventListener('click', ()=>{ builderState.days=Number(b.dataset.days); renderBuilder(); }));
    builderModalBox.querySelectorAll('[data-dur]').forEach(b=>b.addEventListener('click', ()=>{ builderState.duration=Number(b.dataset.dur); renderBuilder(); }));
    builderModalBox.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click', ()=>{
      const id = b.dataset.cat;
      if(builderState.cats.includes(id)) builderState.cats = builderState.cats.filter(c=>c!==id);
      else builderState.cats.push(id);
      renderBuilder();
    }));
    document.getElementById('genPlanBtn').addEventListener('click', generateCustomPlan);
    document.getElementById('builderClose').addEventListener('click', ()=>builderModalBg.classList.remove('show'));
  }

  function generateCustomPlan(){
    const cats = builderState.cats.length ? builderState.cats : exerciseTree.children.map(c=>c.id);
    const days = builderState.days, dur = builderState.duration;
    const palette = ['#3b6fed','#8b6ef2','#22b573','#f0a020','#ef5b6b'];
    const plan = [];
    for(let i=0;i<days;i++){
      const catId = cats[i % cats.length];
      const cat = exerciseTree.children.find(c=>c.id===catId);
      plan.push({ day:'วันที่ '+(i+1), catId:catId, title:cat.name, sub:dur+' นาที | แผนที่คุณกำหนดเอง', tagColor:palette[i%palette.length] });
    }
    weekPlans[1]=plan; weekPlans[2]=plan; weekPlans[3]=plan; weekPlans[4]=plan;
    document.getElementById('planGoalLabel').textContent = 'แผนที่คุณสร้างเอง';
    document.getElementById('planDays').textContent = days+' วัน/สัปดาห์';
    document.getElementById('planKcal').textContent = 'ประมาณ '+Math.round(dur*6)+' kcal';
    document.getElementById('planDuration').textContent = dur+' นาที';
    document.getElementById('settingsGoal').textContent = 'แผนที่คุณสร้างเอง';
    document.querySelectorAll('.goal-card').forEach(c=>c.classList.remove('selected'));
    currentWeek = 1;
    document.querySelectorAll('.week-tab').forEach(t=>t.classList.toggle('active', t.dataset.week==='1'));
    buildDayList();
    builderModalBg.classList.remove('show');
    goTo('plan');
  }

  const openBuilderBtn = document.getElementById('openBuilder');
  if(openBuilderBtn) openBuilderBtn.addEventListener('click', ()=>{ renderBuilder(); builderModalBg.classList.add('show'); });
  builderModalBg.addEventListener('click', (e)=>{ if(e.target===builderModalBg) builderModalBg.classList.remove('show'); });

  /* ============================================================
     MEMBERSHIP / LOGIN (SYSTEM DEMO)
     หมายเหตุ: นี่คือระบบจำลอง (mock) สำหรับสาธิต/ส่งงานเท่านั้น
     ไม่มีการเชื่อมต่อฐานข้อมูลหรือยืนยันตัวตนจริง
  ============================================================ */
  const MEMBERSHIP_TIERS = [
    { id:'bronze',   name:'Bronze',   minKcal:0,     discount:5,  color:'#c98a4b' },
    { id:'silver',   name:'Silver',   minKcal:3000,  discount:10, color:'#9aa4bd' },
    { id:'gold',     name:'Gold',     minKcal:7000,  discount:15, color:'#e0a527' },
    { id:'platinum', name:'Platinum', minKcal:12000, discount:20, color:'#6fa0ff' }
  ];
  const TOTAL_KCAL_BURNED = 7850; // อิงจากค่าที่แสดงในหน้าสถิติ

  let userState = {
    loggedIn: true,
    name: 'สุธีพงษ์',
    email: 'sutheepong@example.com',
    totalKcal: TOTAL_KCAL_BURNED
  };
  let acctView = 'profile'; // 'profile' | 'login' | 'register'

  function getTier(kcal){
    let cur = MEMBERSHIP_TIERS[0];
    for(const t of MEMBERSHIP_TIERS){ if(kcal >= t.minKcal) cur = t; }
    return cur;
  }
  function getNextTier(tier){
    const i = MEMBERSHIP_TIERS.findIndex(t=>t.id===tier.id);
    return MEMBERSHIP_TIERS[i+1] || null;
  }

  function updateUserBadges(){
    const sidebarAvatar = document.getElementById('sidebarAvatar');
    const sidebarName = document.getElementById('sidebarUserName');
    const sidebarTier = document.getElementById('sidebarTier');
    const topAvatar = document.getElementById('topAvatar');
    const topName = document.getElementById('topUserName');
    const topRole = document.getElementById('topUserRole');

    if(!userState.loggedIn){
      sidebarAvatar.textContent = '?';
      sidebarName.textContent = 'ยังไม่เข้าสู่ระบบ';
      sidebarTier.textContent = 'แตะเพื่อเข้าสู่ระบบ';
      topAvatar.textContent = '?';
      topName.textContent = 'ยังไม่เข้าสู่ระบบ';
      topRole.textContent = 'แตะเพื่อเข้าสู่ระบบ';
      return;
    }
    const tier = getTier(userState.totalKcal);
    const initials = userState.name.trim().slice(0,2);
    sidebarAvatar.textContent = initials;
    sidebarName.textContent = 'สวัสดี, '+userState.name;
    sidebarTier.textContent = tier.name+' · ส่วนลด '+tier.discount+'%';
    topAvatar.textContent = initials;
    topName.textContent = 'สวัสดี, '+userState.name;
    topRole.textContent = 'สมาชิก MoveUp · '+tier.name;
  }

  const acctModalBg = document.getElementById('acctModalBg');
  const acctModalBox = document.getElementById('acctModalBox');

  function openAcctModal(){
    acctView = userState.loggedIn ? 'profile' : 'login';
    renderAcctModal();
    acctModalBg.classList.add('show');
  }
  document.getElementById('sidebarUserBtn').addEventListener('click', openAcctModal);
  document.getElementById('topUserBtn').addEventListener('click', openAcctModal);
  acctModalBg.addEventListener('click', (e)=>{ if(e.target===acctModalBg) acctModalBg.classList.remove('show'); });

  function renderAcctModal(){
    if(acctView === 'profile') return renderProfileView();
    return renderAuthView();
  }

  function renderProfileView(){
    const tier = getTier(userState.totalKcal);
    const next = getNextTier(tier);
    const initials = userState.name.trim().slice(0,2);
    let progressHtml = '<div class="progress-note">คุณอยู่ในระดับสูงสุดแล้ว 🎉</div>';
    if(next){
      const span = next.minKcal - tier.minKcal;
      const pct = Math.min(100, Math.round(((userState.totalKcal - tier.minKcal) / span) * 100));
      progressHtml = `
        <div class="progress-track"><div class="progress-fill" style="width:${pct}%;"></div></div>
        <div class="progress-note">อีก ${Math.max(0,next.minKcal - userState.totalKcal)} kcal จะเลื่อนขั้นเป็น <b>${next.name}</b> (ส่วนลด ${next.discount}%)</div>`;
    }
    acctModalBox.innerHTML = `
      <div class="acct-head">
        <div class="avatar">${initials}</div>
        <div>
          <div class="name">${userState.name}</div>
          <div class="email">${userState.email}</div>
        </div>
      </div>
      <div class="acct-box">
        <div class="row"><span>ระดับสมาชิก</span><span class="tier-badge" style="background:${tier.color};">${tier.name}</span></div>
        <div class="row"><span>ส่วนลดค่าคอร์ส/แพ็กเกจ</span><span class="discount-pill">-${tier.discount}%</span></div>
        <div class="row"><span>แคลอรีสะสม</span><span><b>${userState.totalKcal.toLocaleString()}</b> kcal</span></div>
        ${progressHtml}
      </div>
      <button class="logout-btn" id="acctLogout">ออกจากระบบ</button>
      <div class="test-note">⚠️ ระบบสมาชิกและส่วนลดนี้เป็นระบบทดสอบ (mock) สำหรับสาธิต/ส่งงานเท่านั้น ยังไม่เชื่อมต่อระบบชำระเงินหรือฐานข้อมูลจริง</div>
      <button class="modal-close" id="acctClose">ปิด</button>
    `;
    document.getElementById('acctLogout').addEventListener('click', ()=>{
      userState.loggedIn = false;
      updateUserBadges();
      acctView = 'login';
      renderAcctModal();
    });
    document.getElementById('acctClose').addEventListener('click', ()=>acctModalBg.classList.remove('show'));
  }

  function renderAuthView(){
    const isLogin = acctView === 'login';
    acctModalBox.innerHTML = `
      <h3>${isLogin ? 'เข้าสู่ระบบสมาชิก' : 'สมัครสมาชิกใหม่'}</h3>
      <div class="tab-row">
        <button class="tab-btn ${isLogin?'active':''}" id="tabLogin" type="button">เข้าสู่ระบบ</button>
        <button class="tab-btn ${!isLogin?'active':''}" id="tabRegister" type="button">สมัครสมาชิก</button>
      </div>
      <form id="acctForm">
        ${!isLogin ? `<div class="form-field"><label>ชื่อ-นามสกุล</label><input type="text" id="fName" placeholder="เช่น สุธีพงษ์ ใจดี" required></div>` : ''}
        <div class="form-field"><label>อีเมล</label><input type="email" id="fEmail" placeholder="you@example.com" required></div>
        <div class="form-field"><label>รหัสผ่าน</label><input type="password" id="fPass" placeholder="อย่างน้อย 4 ตัวอักษร" required></div>
        <div class="form-error" id="fError">กรุณากรอกข้อมูลให้ครบถ้วน (อย่างน้อย 4 ตัวอักษร)</div>
        <button class="btn" type="submit" style="width:100%; justify-content:center;">${isLogin ? 'เข้าสู่ระบบ' : 'สมัครสมาชิก'}</button>
      </form>
      <div class="switch-line">
        ${isLogin ? 'ยังไม่มีบัญชี? ' : 'มีบัญชีอยู่แล้ว? '}
        <button id="acctSwitch" type="button">${isLogin ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ'}</button>
      </div>
      <div class="test-note">⚠️ นี่คือระบบเข้าสู่ระบบจำลอง (test) สำหรับใช้สาธิต/ส่งงานอาจารย์เท่านั้น ไม่มีการตรวจสอบรหัสผ่านจริงหรือเก็บข้อมูลลงฐานข้อมูล กรอกข้อมูลใดก็ได้เพื่อทดสอบ</div>
      <button class="modal-close" id="acctClose2">ปิด</button>
    `;
    document.getElementById('tabLogin').addEventListener('click', ()=>{ acctView='login'; renderAcctModal(); });
    document.getElementById('tabRegister').addEventListener('click', ()=>{ acctView='register'; renderAcctModal(); });
    document.getElementById('acctSwitch').addEventListener('click', ()=>{ acctView = isLogin ? 'register' : 'login'; renderAcctModal(); });
    document.getElementById('acctClose2').addEventListener('click', ()=>acctModalBg.classList.remove('show'));

    document.getElementById('acctForm').addEventListener('submit', (e)=>{
      e.preventDefault();
      const email = document.getElementById('fEmail').value.trim();
      const pass = document.getElementById('fPass').value.trim();
      const nameField = document.getElementById('fName');
      const name = nameField ? nameField.value.trim() : userState.name;
      const err = document.getElementById('fError');
      if(!email || pass.length < 4 || (!isLogin && !name)){
        err.classList.add('show');
        return;
      }
      err.classList.remove('show');
      // ระบบทดสอบ: ยอมรับข้อมูลใดๆ ที่ผ่านการตรวจสอบขั้นต้น แล้วจำลองว่าเข้าสู่ระบบสำเร็จ
      userState.loggedIn = true;
      userState.email = email;
      if(!isLogin && name) userState.name = name;
      updateUserBadges();
      acctView = 'profile';
      renderAcctModal();
    });
  }

  updateUserBadges();

})();
